#include "FreeRTOS.h"
#include "task.h"

#include "main.h"     /* HAL + CubeMX GPIO defines from template/ */
#include "params.h"   /* generated by tools/gen_params.py */
#include <stm32f103xb.h>

/* TODO 1: build the GPIO port/pin pair for PA<BLINK_GPIO_PIN>.
 *         Hint: GPIO_PIN_0 .. GPIO_PIN_15 are bit masks, not indices. */
static GPIO_TypeDef * const gpio_blink_port = GPIOA;
static const uint16_t gpio_blink_pin = (uint16_t)(1U << BLINK_GPIO_PIN);

/* TODO 2: implement the bring-up task.
 *         - toggle the pin
 *         - block for BLINK_PERIOD_MS using vTaskDelay()
 *         - the task must never return */
static void vBringup_task(void *argument)
{
    (void)argument;

    for (;;) {
        HAL_GPIO_TogglePin(gpio_blink_port, gpio_blink_pin);
        vTaskDelay(pdMS_TO_TICKS(BLINK_PERIOD_MS / 2));
    }
}

void app_main(void)
{
    /* TODO 3: create bringup_task with stack BRINGUP_STACK_WORDS and a priority
     *         you can justify. Check the return value — do not ignore it. */
    BaseType_t status = xTaskCreate(vBringup_task, "bring-up", BRINGUP_STACK_WORDS, NULL, 1, NULL);
    if (status != pdPASS) {
        for (;;) {
            // if create task fail => LED active low
            HAL_GPIO_WritePin(gpio_blink_port, gpio_blink_pin, GPIO_PIN_RESET);
        }
    }

    /* TODO 4: start the scheduler. */
    vTaskStartScheduler();
    /* Reaching this point means the scheduler returned: out of heap, or the
     * handlers in TODO 5 were never mapped. Trap here so it is visible. */
    for (;;) {
    }
}

